function minFlips(target) {
  const n = target.length;
  if (n <= 16) {
    // Breadth-first search over every string s, one suffix flip per edge, from all zeros to target.
    let goal = 0;
    for (let i = 0; i < n; i++) if (target[i] === '1') goal |= 1 << i;
    const dist = new Array(1 << n).fill(-1);
    dist[0] = 0;
    const queue = [0];
    for (let head = 0; head < queue.length; head++) {
      const state = queue[head];
      if (state === goal) return dist[state];
      for (let i = 0; i < n; i++) {
        const next = state ^ (((1 << n) - 1) & ~((1 << i) - 1));
        if (dist[next] === -1) {
          dist[next] = dist[state] + 1;
          queue.push(next);
        }
      }
    }
    return -1;
  }
  // Longer strings: flip a real array whenever the leftmost wrong bit is found.
  const s = new Array(n).fill('0');
  let moves = 0;
  for (let i = 0; i < n; i++) {
    if (s[i] !== target[i]) {
      moves++;
      for (let j = i; j < n; j++) s[j] = s[j] === '0' ? '1' : '0';
    }
  }
  return moves;
}

