function generate(rand, size) {
  const n = size === 'large' ? 9000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 12);
  // switchChance controls how often the next bit differs from the previous one: low gives long runs, high alternates.
  const switchChance = [0.05, 0.3, 0.5, 0.8, 0.98][Math.floor(rand() * 5)];
  let bit = rand() < 0.5 ? '0' : '1';
  let target = '';
  for (let i = 0; i < n; i++) {
    if (i > 0 && rand() < switchChance) bit = bit === '0' ? '1' : '0';
    target += bit;
  }
  return [target];
}
